{
  "mode": "server",
  "server": "user-Gmail",
  "serverStatus": "ready",
  "tools": [
    {
      "tool": "apply_sensitive_message_label",
      "description": "Adds a sensitive label (Trash or Spam) to a single message in the authenticated user's Gmail account. Use `apply_sensitive_message_label` when applying Trash or Spam to exactly 1 message. To apply sensitive labels to multiple messages, use `batch_apply_sensitive_message_labels` instead. If the message belongs to a thread that should be labeled as a whole, prefer `apply_sensitive_thread_label`. To find the message ID, use tools like `search_threads` or `get_thread`. To find the draft message ID, use tools like `list_drafts`.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "labelOption": {
            "description": "Required. The sensitive label option to add.",
            "enum": [
              "LABEL_OPTION_UNSPECIFIED",
              "TRASH",
              "SPAM"
            ],
            "type": "string",
            "x-google-enum-descriptions": [
              "Unspecified label option.",
              "Trash label.",
              "Spam label."
            ]
          },
          "messageId": {
            "description": "Required. The ID of the message to add the label to.",
            "type": "string"
          }
        },
        "required": [
          "messageId",
          "labelOption"
        ],
        "description": "Request message for ApplySensitiveMessageLabel RPC."
      }
    },
    {
      "tool": "apply_sensitive_thread_label",
      "description": "Adds a sensitive label (Trash or Spam) to a single thread in the authenticated user's Gmail account. This operation affects all messages currently in the thread. Use `apply_sensitive_thread_label` when applying Trash or Spam to exactly 1 thread. To apply sensitive labels to multiple threads, use `batch_apply_sensitive_thread_labels` instead. To find the thread ID, use the `search_threads` tool first.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "labelOption": {
            "description": "Required. The sensitive label option to add.",
            "enum": [
              "LABEL_OPTION_UNSPECIFIED",
              "TRASH",
              "SPAM"
            ],
            "type": "string",
            "x-google-enum-descriptions": [
              "Unspecified label option.",
              "Trash label.",
              "Spam label."
            ]
          },
          "threadId": {
            "description": "Required. The ID of the thread to add the label to.",
            "type": "string"
          }
        },
        "required": [
          "threadId",
          "labelOption"
        ],
        "description": "Request message for ApplySensitiveThreadLabel RPC."
      }
    },
    {
      "tool": "create_draft",
      "description": "Creates a new draft email in the authenticated user's Gmail account. This tool takes recipient addresses, a subject, and body content as inputs. If the draft is created as a reply to an existing message, the ID of the original message should be passed to the tool in the replyToMessageId field. Returns a Draft object with the `id` and `threadId` fields populated.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "attachments": {
            "description": "Optional. The attachments to include in the email. The combined size of attachments in the message cannot exceed 25MB. If you need to send files larger than 25MB, upload the file to Drive first and then insert the Drive link into `body` or `html_body`.",
            "items": {
              "$ref": "#/$defs/Attachment"
            },
            "type": "array"
          },
          "bcc": {
            "description": "Optional. The blind carbon copy recipients of the email draft. Each string MUST be a valid plain email address (e.g., \"user@example.com\").",
            "items": {
              "type": "string"
            },
            "type": "array"
          },
          "body": {
            "description": "Optional. The main body content of the email draft. If `html_body` is also provided, this field is treated as the plain-text alternative.",
            "type": "string"
          },
          "cc": {
            "description": "Optional. The carbon copy recipients of the email draft. Each string MUST be a valid plain email address (e.g., \"user@example.com\").",
            "items": {
              "type": "string"
            },
            "type": "array"
          },
          "htmlBody": {
            "description": "The HTML content of the email draft. If provided, this will be used as the rich-text version of the email.",
            "type": "string"
          },
          "replyToMessageId": {
            "description": "Optional. The ID of the message to reply to. If provided, this will be used as the reply-to message ID for the email draft, and the `body` and `html_body` will be appended to the original message body.",
            "type": "string"
          },
          "subject": {
            "description": "Optional. The subject line of the email. Defaults to empty if not provided.",
            "type": "string"
          },
          "to": {
            "description": "Optional. The primary recipients of the email draft. Each string MUST be a valid plain email address (e.g., \"user@example.com\").",
            "items": {
              "type": "string"
            },
            "type": "array"
          }
        },
        "$defs": {
          "Attachment": {
            "description": "Represents an attachment to be included in an email.",
            "properties": {
              "content": {
                "description": "Required. The base64-encoded content of the attachment.",
                "format": "byte",
                "type": "string"
              },
              "filename": {
                "description": "Optional. The name of the file to be attached, e.g. \"invoice.pdf\". For inline attachments, this is used for Content-ID generation. For regular attachments, filename is used to specify the filename to email clients. If not provided, the attachment may be received with no name.",
                "type": "string"
              },
              "id": {
                "description": "Optional. Output only. When present, contains the ID of an external attachment that can be retrieved in a separate `GetMessageAttachment` request.",
                "readOnly": true,
                "type": "string"
              },
              "inline": {
                "description": "Optional. If true, this attachment is handled as inline. An inline attachment is a content that is intended to be displayed within the body of an HTML email, as opposed to being listed as a separate file for download. If false or absent, defaults to false, and it's treated as a regular attachment.",
                "type": "boolean"
              },
              "mimeType": {
                "description": "Optional. The field representing a content or media type must use IANA MIME type, https://www.iana.org/assignments/media-types/media-types.xhtml. If not provided, defaults to \"application/octet-stream\".",
                "type": "string"
              }
            },
            "required": [
              "content"
            ],
            "type": "object"
          }
        },
        "description": "Request message for CreateDraft RPC."
      }
    },
    {
      "tool": "create_filter",
      "description": "Creates a new filter in the authenticated user's Gmail account.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "action": {
            "$ref": "#/$defs/FilterAction",
            "description": "Required. The action to perform on matching messages."
          },
          "criteria": {
            "$ref": "#/$defs/FilterCriteria",
            "description": "Required. The criteria for matching messages."
          }
        },
        "required": [
          "criteria",
          "action"
        ],
        "$defs": {
          "FilterAction": {
            "description": "A set of actions to perform on a message.",
            "properties": {
              "addLabelIds": {
                "description": "List of labels to add to the message.",
                "items": {
                  "type": "string"
                },
                "type": "array"
              },
              "removeLabelIds": {
                "description": "List of labels to remove from the message.",
                "items": {
                  "type": "string"
                },
                "type": "array"
              }
            },
            "type": "object"
          },
          "FilterCriteria": {
            "description": "Matching criteria for the filter.",
            "properties": {
              "containWords": {
                "description": "Optional. Words that the message must contain.",
                "items": {
                  "type": "string"
                },
                "type": "array"
              },
              "doesNotContainWords": {
                "description": "Optional. Words that the message must not contain.",
                "items": {
                  "type": "string"
                },
                "type": "array"
              },
              "from": {
                "description": "Optional. The sender's display name or email address. The \"Name \" format is NOT supported by this tool.",
                "type": "string"
              },
              "hasAttachment": {
                "description": "Optional. Whether the message has any attachment.",
                "type": "boolean"
              },
              "size": {
                "description": "Optional. The size of the entire RFC822 message in bytes. Must be specified together with `size_comparison`.",
                "format": "int32",
                "type": "integer"
              },
              "sizeComparison": {
                "description": "Optional. How the message size in bytes should be in relation to the `size` field. Must be specified together with `size`.",
                "enum": [
                  "SIZE_COMPARISON_UNSPECIFIED",
                  "SMALLER",
                  "LARGER"
                ],
                "type": "string",
                "x-google-enum-descriptions": [
                  "Defaults to UNSPECIFIED.",
                  "The message size should be smaller than the size field.",
                  "The message size should be larger than the size field."
                ]
              },
              "subject": {
                "description": "Optional. Case-insensitive phrase found in the message's subject.",
                "type": "string"
              },
              "to": {
                "description": "Optional. The recipient's display name or email address. The \"Name \" format is NOT supported by this tool.",
                "type": "string"
              }
            },
            "type": "object"
          }
        },
        "description": "Request message for CreateFilter RPC."
      }
    },
    {
      "tool": "create_label",
      "description": "Creates a new label in the authenticated user's Gmail account. Supports creating nested labels (sub-labels) using a forward slash (e.g., 'Projects/Alpha/Sprint-1'). By default, parent labels will be automatically created if they do not exist.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "autoCreateParentLabels": {
            "description": "Optional. Whether to automatically create parent labels for nested labels (separated by '/'). Defaults to true.",
            "type": "boolean"
          },
          "color": {
            "$ref": "#/$defs/LabelColor",
            "deprecated": true,
            "description": "Deprecated: Do not use. Use color_preset instead. Legacy field for raw text and background color hex strings."
          },
          "colorPreset": {
            "description": "Optional. The color preset tile to assign to the new label. Select from predefined contrast-safe color options (e.g., LABEL_COLOR_PRESET_RED, LABEL_COLOR_PRESET_BLUE, LABEL_COLOR_PRESET_BLACK, LABEL_COLOR_PRESET_GREEN). If omitted, default label styling is applied.",
            "enum": [
              "LABEL_COLOR_PRESET_UNSPECIFIED",
              "LABEL_COLOR_PRESET_BLACK",
              "LABEL_COLOR_PRESET_DARK_GRAY",
              "LABEL_COLOR_PRESET_GRAY",
              "LABEL_COLOR_PRESET_LIGHT_GRAY",
              "LABEL_COLOR_PRESET_WHITE",
              "LABEL_COLOR_PRESET_RED",
              "LABEL_COLOR_PRESET_ORANGE",
              "LABEL_COLOR_PRESET_YELLOW",
              "LABEL_COLOR_PRESET_GREEN",
              "LABEL_COLOR_PRESET_MINT",
              "LABEL_COLOR_PRESET_TEAL",
              "LABEL_COLOR_PRESET_BLUE",
              "LABEL_COLOR_PRESET_PURPLE",
              "LABEL_COLOR_PRESET_PINK",
              "LABEL_COLOR_PRESET_DARK_RED",
              "LABEL_COLOR_PRESET_DARK_ORANGE",
              "LABEL_COLOR_PRESET_DARK_GREEN",
              "LABEL_COLOR_PRESET_DARK_BLUE",
              "LABEL_COLOR_PRESET_DARK_PURPLE",
              "LABEL_COLOR_PRESET_DARK_PINK",
              "LABEL_COLOR_PRESET_BROWN"
            ],
            "type": "string",
            "x-google-enum-descriptions": [
              "Default unspecified label color preset.",
              "Black label color tile (#000000 background with #ffffff text).",
              "Dark Gray label color tile (#434343 background with #ffffff text).",
              "Gray label color tile (#666666 background with #ffffff text).",
              "Light Gray label color tile (#cccccc background with #000000 text).",
              "White label color tile (#ffffff background with #000000 text).",
              "Red label color tile (#fb4c2f background with #ffffff text).",
              "Orange label color tile (#ffad47 background with #000000 text).",
              "Yellow label color tile (#fad165 background with #000000 text).",
              "Green label color tile (#16a765 background with #ffffff text).",
              "Mint label color tile (#43d692 background with #000000 text).",
              "Teal label color tile (#2da2bb background with #ffffff text).",
              "Blue label color tile (#4a86e8 background with #ffffff text).",
              "Purple label color tile (#a479e2 background with #ffffff text).",
              "Pink label color tile (#f691b2 background with #000000 text).",
              "Dark Red label color tile (#822111 background with #ffffff text).",
              "Dark Orange label color tile (#a46a21 background with #ffffff text).",
              "Dark Green label color tile (#076239 background with #ffffff text).",
              "Dark Blue label color tile (#1c4587 background with #ffffff text).",
              "Dark Purple label color tile (#41236d background with #ffffff text).",
              "Dark Pink label color tile (#83334c background with #ffffff text).",
              "Brown label color tile (#7a4706 background with #ffffff text)."
            ]
          },
          "displayName": {
            "description": "Required. The display name of the label to create.",
            "type": "string"
          }
        },
        "required": [
          "displayName"
        ],
        "$defs": {
          "LabelColor": {
            "description": "Deprecated: Do not use. Use LabelColorPreset instead. The color of the label.",
            "properties": {
              "backgroundColor": {
                "deprecated": true,
                "description": "Deprecated: Do not use. Use LabelColorPreset instead. The background color of the label, specified as either a 6-digit hex string (e.g., `#000000`) or a supported color name.",
                "type": "string"
              },
              "textColor": {
                "deprecated": true,
                "description": "Deprecated: Do not use. Use LabelColorPreset instead. The text color of the label, specified as either a 6-digit hex string (e.g., `#ffffff`) or a supported color name.",
                "type": "string"
              }
            },
            "type": "object"
          }
        },
        "description": "Request message for CreateLabel RPC."
      }
    },
    {
      "tool": "delete_label",
      "description": "Deletes a label in the authenticated user's Gmail account.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "labelId": {
            "description": "Required. The ID of the label to delete.",
            "type": "string"
          }
        },
        "required": [
          "labelId"
        ],
        "description": "Request message for DeleteLabel RPC."
      }
    },
    {
      "tool": "forward",
      "description": "Forwards a specific email message in the authenticated user's Gmail account. Returns a Message object with the `id`, `threadId`, and `labelIds` fields populated.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "bcc": {
            "description": "Optional. The blind carbon copy recipients of the email. Each string MUST be a valid plain email address (e.g., \"user@example.com\"). The \"Name \" format is NOT supported by this tool.",
            "items": {
              "type": "string"
            },
            "type": "array"
          },
          "cc": {
            "description": "Optional. The carbon copy recipients of the email. Each string MUST be a valid plain email address (e.g., \"user@example.com\"). The \"Name \" format is NOT supported by this tool.",
            "items": {
              "type": "string"
            },
            "type": "array"
          },
          "forwardText": {
            "description": "Optional. Comments to add before the forwarded message.",
            "type": "string"
          },
          "htmlBody": {
            "description": "Optional. The HTML content of the comments to add before the forwarded message. If provided, this will be used as the rich-text version of the forward comments.",
            "type": "string"
          },
          "messageId": {
            "description": "Required. The unique identifier of the message to forward. A specific `message_id` is required to forward, which can be obtained by retrieving the thread via `get_thread`.",
            "type": "string"
          },
          "to": {
            "description": "Optional. The primary recipients of the email. Each string MUST be a valid plain email address (e.g., \"user@example.com\"). The \"Name \" format is NOT supported by this tool.",
            "items": {
              "type": "string"
            },
            "type": "array"
          }
        },
        "required": [
          "messageId"
        ],
        "description": "Request message for Forward RPC."
      }
    },
    {
      "tool": "get_message",
      "description": "Retrieves a specific email message from the authenticated user's Gmail account by its unique message ID. Use this tool to inspect a single, individual email when you already know its message ID. If the user wants to read a specific email in detail, check the exact wording of a message, or examine attachment metadata for a single email, this is the right tool. It is not suitable for retrieving entire conversations or viewing back-and-forth discussion threads; use the 'get_thread' tool instead. Key indicators include if the user asks for the full content of a specific message ID returned by a previous search, or if the query asks to inspect a specific individual email rather than an entire thread. Example user prompts are: \"Get the full text of message ID 18f123456789abcd.\", \"Read the latest message in that thread from Alice.\", and \"What are the attachment names in the email I just received from HR?\" The optional `messageFormat` parameter controls the format of the message returned. By default (or with `FULL_CONTENT`), it returns the full content of the message. We recommend using `PLAIN_TEXT`, which returns the plain text body without the HTML body. Use `MINIMAL` to include only subject and snippet (excluding body). Use `METADATA_ONLY` to include only basic metadata (message ID, thread ID, labels, timestamp, and size estimate).",
      "inputSchema": {
        "type": "object",
        "properties": {
          "messageFormat": {
            "description": "Optional. Specifies the format of the message returned. Defaults to FULL_CONTENT. We recommend using PLAIN_TEXT to prevent context exhaustion.",
            "enum": [
              "MESSAGE_FORMAT_UNSPECIFIED",
              "MINIMAL",
              "FULL_CONTENT",
              "METADATA_ONLY",
              "PLAIN_TEXT",
              "RAW"
            ],
            "type": "string",
            "x-google-enum-descriptions": [
              "Defaults to FULL_CONTENT.",
              "Returns message snippets and key headers (Subject, From, To, Cc, Date).",
              "Returns all information in \"MINIMAL\" plus the full body content of each message.",
              "Metadata only: does not include subject, snippet, body, attachment filenames.",
              "Returns all information in \"MINIMAL\" plus the plain text body content of each message. If plain text body is not available, converts the HTML body to plain text/markdown. Does not include htmlBody.",
              "Returns the raw MIME message content."
            ]
          },
          "messageId": {
            "description": "Required. The unique identifier of the message to fetch.",
            "type": "string"
          }
        },
        "required": [
          "messageId"
        ],
        "description": "Request message for GetMessage RPC."
      }
    },
    {
      "tool": "get_thread",
      "description": "Retrieves a specific email thread from the authenticated user's Gmail account, including a list of its messages. The optional `messageFormat` parameter controls the format of the messages returned. By default (or with `FULL_CONTENT`), it returns the full content of messages. We recommend using `PLAIN_TEXT`, which returns the plain text body without the HTML body. Use `MINIMAL` to include only subject and snippet (excluding body). Use `METADATA_ONLY` to include only basic metadata (message ID, thread ID, labels, timestamp, and size estimate).",
      "inputSchema": {
        "type": "object",
        "properties": {
          "messageFormat": {
            "description": "Optional. Specifies the format of the messages returned within the thread. Defaults to `FULL_CONTENT`. We recommend using `PLAIN_TEXT` to prevent context exhaustion. Note: `MINIMAL` format returns `id`, `snippet`, `subject`, `sender`, `to_recipients`, `cc_recipients`, `bcc_recipients`, `date`, `label_ids`. `METADATA_ONLY` format returns `id`, `sender`, `to_recipients`, `cc_recipients`, `bcc_recipients`, `date`, `label_ids`. `FULL_CONTENT` returns `id`, `snippet`, `subject`, `sender`, `to_recipients`, `cc_recipients`, `bcc_recipients`, `date`, `label_ids`, `attachment_ids`, `plaintext_body`, `html_body`, `attachments`. `PLAIN_TEXT` returns `id`, `snippet`, `subject`, `sender`, `to_recipients`, `cc_recipients`, `bcc_recipients`, `date`, `label_ids`, `attachment_ids`, `plaintext_body`, `attachments` (without `html_body`).",
            "enum": [
              "MESSAGE_FORMAT_UNSPECIFIED",
              "MINIMAL",
              "FULL_CONTENT",
              "METADATA_ONLY",
              "PLAIN_TEXT",
              "RAW"
            ],
            "type": "string",
            "x-google-enum-descriptions": [
              "Defaults to FULL_CONTENT.",
              "Returns message snippets and key headers (Subject, From, To, Cc, Date).",
              "Returns all information in \"MINIMAL\" plus the full body content of each message.",
              "Metadata only: does not include subject, snippet, body, attachment filenames.",
              "Returns all information in \"MINIMAL\" plus the plain text body content of each message. If plain text body is not available, converts the HTML body to plain text/markdown. Does not include htmlBody.",
              "Returns the raw MIME message content."
            ]
          },
          "threadId": {
            "description": "Required. The unique identifier of the thread to fetch.",
            "type": "string"
          }
        },
        "required": [
          "threadId"
        ],
        "description": "Request message for GetThread RPC."
      }
    },
    {
      "tool": "label_message",
      "description": "Adds one or more labels to a specific message in the authenticated user's Gmail account. To find the message ID, use tools like `search_threads` or `get_thread`. If unsure of a user label's ID, use the `list_labels` tool first to discover available labels and their IDs. To add a Trash label or a Spam label to a message, or move a specific message to Trash, please use the `apply_sensitive_message_label` tool instead.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "labelIds": {
            "description": "Required. The IDs of the labels to add. Can be a system label ID (e.g., `INBOX`, `STARRED`, `UNREAD`, `IMPORTANT`) or a user-defined label ID. The tool accepts `label_ids` and not label names. Use the `list_labels` tool to get the corresponding label id to a display name for user-defined labels.",
            "items": {
              "type": "string"
            },
            "type": "array"
          },
          "messageId": {
            "description": "Required. The ID of the message to add the labels to.",
            "type": "string"
          }
        },
        "required": [
          "messageId",
          "labelIds"
        ],
        "description": "Request message for LabelMessage RPC."
      }
    },
    {
      "tool": "label_thread",
      "description": "Adds labels to an entire thread in the authenticated user's Gmail account. This operation affects all messages currently in the thread and any future messages added to it. If unsure of the thread ID, use the `search_threads` tool first. If unsure of a user label's ID, use the `list_labels` tool first to discover available labels and their IDs. To add a Trash label or a Spam label to a thread, or move a specific thread to Trash, please use the `apply_sensitive_thread_label` tool instead.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "labelIds": {
            "description": "Required. The unique identifiers of the labels to add. Can be a system label ID (e.g., `INBOX`, `STARRED`, `UNREAD`, `IMPORTANT`) or a user-defined label ID. The tool accepts `label_ids` and not label names. Use the `list_labels` tool to get the corresponding label id to a display name for user-defined labels.",
            "items": {
              "type": "string"
            },
            "type": "array"
          },
          "threadId": {
            "description": "Required. The unique identifier of the thread to add labels to.",
            "type": "string"
          }
        },
        "required": [
          "threadId",
          "labelIds"
        ],
        "description": "Request message for LabelThread RPC."
      }
    },
    {
      "tool": "list_drafts",
      "description": "Lists draft emails from the authenticated user's Gmail account. This tool can filter drafts based on a query string and supports pagination. It returns a list of drafts, including their IDs and subjects (unless `view` is set to `DRAFT_VIEW_METADATA_ONLY`). `page_token` can be used to paginate the results. To retrieve subsequent pages of results, use the `page_token` returned in the previous response. The `view` parameter controls which fields are populated in the response. By default (or with `DRAFT_VIEW_FULL`), it returns full content. Use `DRAFT_VIEW_METADATA_ONLY` to exclude sensitive content like subject and body. Note: An empty JSON object `{}` represents zero matching items, not an error.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "pageSize": {
            "description": "Optional. The maximum number of drafts to return. If unspecified, defaults to 20. The maximum allowed value is 50.",
            "format": "int32",
            "type": "integer"
          },
          "pageToken": {
            "description": "Optional. A token received from a previous list_drafts call to retrieve the next page of results. Leave empty to fetch the first page. This is primarily used for pagination to continue fetching results from where the previous `ListDraft` call left off, especially when the number of drafts matching the query exceeds the page_size limit.",
            "type": "string"
          },
          "query": {
            "description": "Examples: - `subject:OneMCP Update` - `from:gduser1@workspacesamples.dev` - `to:gduser2@workspacesamples.dev AND newer_than:7d` - `project proposal has:attachment` - `is:unread` A space or a dash (`-`) will separate a number while a dot (`.`) will be a decimal. For example, `01.2047-100` is considered two numbers: `01.2047` and `100`. Note: If we want to ensure all drafts for the query are returned, we can paginate the results by making repeated calls to the tool until the response contains an empty list of drafts.",
            "type": "string"
          },
          "view": {
            "description": "Optional. Controls the fields populated for drafts in the draft list. Defaults to returning metadata only (`id`, `thread_id`, `to_recipients`, `cc_recipients`, `bcc_recipients`, `date`). Set to `DRAFT_VIEW_FULL` to include `subject` and `plaintext_body` content.",
            "enum": [
              "DRAFT_VIEW_UNSPECIFIED",
              "DRAFT_VIEW_METADATA_ONLY",
              "DRAFT_VIEW_FULL"
            ],
            "type": "string",
            "x-google-enum-descriptions": [
              "Unspecified view. Defaults to DRAFT_VIEW_METADATA_ONLY.",
              "Returns metadata only (`id`, `thread_id`, `to_recipients`, `cc_recipients`, `bcc_recipients`, `date`); omits `subject` and `plaintext_body` content.",
              "Returns full draft content, including `subject` and `plaintext_body` in addition to draft metadata."
            ]
